use super::{BrowserEngine, send};
use serde_json::{Value, json};

#[test]
fn tournament_mcts_recordings_load_and_allow_navigation_in_the_browser() {
    // Generated by the tournament runner: MCTS (5 iterations, rollout length 1)
    // versus Random, master seed 42. Connect 4 uses a 5x4 board and target 3.
    for text in [
        include_str!("../../../../examples/saves/tournament-tictactoe.tag-replay.json"),
        include_str!("../../../../examples/saves/tournament-connect4.tag-replay.json"),
    ] {
        let recording: Value = serde_json::from_str(text).unwrap();
        let moves = recording["branches"][0]["moves"].as_array().unwrap();
        let mut engine = BrowserEngine::new();
        let loaded = file(
            &mut engine,
            "0",
            json!({"type":"import","controllers":null}),
            text,
        );
        assert!(loaded["error"].is_null(), "{loaded}");
        assert_eq!(loaded["view"]["cursor"], moves.len());
        assert!(loaded["view"]["next_player"].is_null());
        assert_eq!(
            loaded["view"]["controllers"],
            json!([{"kind":"human"},{"kind":"human"}])
        );
        for cursor in 0..=moves.len() {
            let reply = send(
                &mut engine,
                "1",
                None,
                json!({"type":"history","branch":0,"cursor":cursor}),
            );
            assert!(reply["error"].is_null(), "{reply}");
            assert_eq!(reply["view"]["cursor"], cursor);
            assert_eq!(
                reply["view"]["board"]["cells"]
                    .as_array()
                    .unwrap()
                    .iter()
                    .filter(|cell| !cell.is_null())
                    .count(),
                cursor
            );
        }
    }
}

pub(super) fn file(
    engine: &mut BrowserEngine,
    generation: &str,
    command: Value,
    text: &str,
) -> Value {
    serde_json::from_str(&engine.handle_file(
        &json!({"request_id":"9","generation":generation,"command":command}).to_string(),
        text,
    ))
    .unwrap()
}
pub(super) fn step(engine: &mut BrowserEngine, generation: &str, view: &Value) -> Value {
    let prepared = send(
        engine,
        generation,
        view["position_version"].as_str(),
        json!({"type":"prepare_ai"}),
    );
    assert!(prepared["error"].is_null(), "{prepared}");
    let reply = send(
        engine,
        generation,
        view["position_version"].as_str(),
        json!({"type":"commit_ai","proposal":prepared["proposal"]["id"]}),
    );
    assert!(reply["error"].is_null(), "{reply}");
    reply["view"].clone()
}
#[test]
fn all_three_exports_restore_positions_controllers_and_exact_continuation() {
    for game in ["tictactoe", "connect4"] {
        let mut original = BrowserEngine::new();
        let mut view = send(&mut original, "0", None, json!({"type":"create","game":game,"controllers":[{"kind":"osla","seed":"18446744073709551615"},{"kind":"osla","seed":"8"}]}))["view"].clone();
        for _ in 0..4 {
            view = step(&mut original, "1", &view);
        }
        view = send(
            &mut original,
            "1",
            view["position_version"].as_str(),
            json!({"type":"fork","branch":0,"cursor":2,"replacements":[{"kind":"human"},null]}),
        )["view"]
            .clone();
        view = send(
            &mut original,
            "1",
            view["position_version"].as_str(),
            json!({"type":"human_move","actor":0,"action":view["actions"][0]}),
        )["view"]
            .clone();
        assert!(view["board"].is_object());
        let mut sources = Vec::new();
        for cursor in 0..=3 {
            sources.push(
                send(
                    &mut original,
                    "1",
                    None,
                    json!({"type":"history","branch":1,"cursor":cursor}),
                )["view"]
                    .clone(),
            );
        }
        let session = file(
            &mut original,
            "1",
            json!({"type":"export","scope":"session","cursor":1,"delay_ms":234}),
            "",
        );
        let branch = file(
            &mut original,
            "1",
            json!({"type":"export","scope":"branch","cursor":1,"delay_ms":234}),
            "",
        );
        let state = file(
            &mut original,
            "1",
            json!({"type":"export","scope":"state","cursor":1,"delay_ms":234}),
            "",
        );
        for export in [&session, &branch, &state] {
            assert!(export["error"].is_null(), "{export}");
        }
        let line: Value = serde_json::from_str(branch["text"].as_str().unwrap()).unwrap();
        assert_eq!(line["branches"].as_array().unwrap().len(), 1);
        assert!(line["branches"][0]["parent"].is_null());
        assert_eq!(line["branches"][0]["moves"].as_array().unwrap().len(), 3);
        assert_eq!(line["versions"]["format"], 2);
        assert_eq!(line["branches"][0]["controller_changes"][0]["position"], 2);
        let expected = step(&mut original, "1", &view);
        for (export, selected, branches) in [(&session, 1, 2), (&branch, 0, 1)] {
            let mut loaded = BrowserEngine::new();
            let reply = file(
                &mut loaded,
                "0",
                json!({"type":"import","controllers":null}),
                export["text"].as_str().unwrap(),
            );
            assert!(reply["error"].is_null(), "{reply}");
            assert_eq!(reply["view"]["cursor"], 1);
            assert_eq!(reply["delay_ms"], 234);
            assert_eq!(
                reply["view"]["branches"].as_array().unwrap().len(),
                branches
            );
            for (cursor, source) in sources.iter().enumerate() {
                let actual = send(
                    &mut loaded,
                    "1",
                    None,
                    json!({"type":"history","branch":selected,"cursor":cursor}),
                );
                for key in ["board", "controllers", "next_player"] {
                    assert_eq!(
                        actual["view"][key], source[key],
                        "{game} cursor {cursor} {key}"
                    );
                }
            }
            let after = step(&mut loaded, "1", &reply["live_view"]);
            assert_eq!(after["board"], expected["board"]);
            // Re-export a flattened line with controller boundaries and load it again.
            let exported = file(
                &mut loaded,
                "1",
                json!({"type":"export","scope":"session","cursor":2,"delay_ms":0}),
                "",
            );
            let round = file(
                &mut BrowserEngine::new(),
                "0",
                json!({"type":"import","controllers":null}),
                exported["text"].as_str().unwrap(),
            );
            assert!(round["error"].is_null(), "{round}");
        }
        let mut loaded = BrowserEngine::new();
        let reply = file(
            &mut loaded,
            "0",
            json!({"type":"import","controllers":[{"kind":"human"},{"kind":"first_available","seed":"9"}]}),
            state["text"].as_str().unwrap(),
        );
        assert!(reply["error"].is_null(), "{reply}");
        assert_eq!(reply["view"]["cursor"], 0);
        assert_eq!(reply["view"]["board"], sources[1]["board"]);
        let reset = send(
            &mut loaded,
            "1",
            reply["live_view"]["position_version"].as_str(),
            json!({"type":"reset"}),
        );
        assert_eq!(reset["view"]["board"], sources[1]["board"]);
    }
}

#[test]
fn branch_exports_drop_unused_ancestry_and_preserve_nested_takeover_boundaries() {
    for game in ["tictactoe", "connect4"] {
        let mut original = BrowserEngine::new();
        let mut view = send(&mut original, "0", None, json!({"type":"create","game":game,"controllers":[{"kind":"osla","seed":"7"},{"kind":"osla","seed":"8"}]}))["view"].clone();
        for _ in 0..4 {
            view = step(&mut original, "1", &view);
        }
        view = send(
            &mut original,
            "1",
            view["position_version"].as_str(),
            json!({"type":"fork","branch":0,"cursor":2,"replacements":[{"kind":"human"},null]}),
        )["view"]
            .clone();
        view = send(
            &mut original,
            "1",
            view["position_version"].as_str(),
            json!({"type":"fork","branch":1,"cursor":1,"replacements":[null,{"kind":"human"}]}),
        )["view"]
            .clone();
        view = send(
            &mut original,
            "1",
            view["position_version"].as_str(),
            json!({"type":"human_move","actor":1,"action":view["actions"][0]}),
        )["view"]
            .clone();
        let exported = file(
            &mut original,
            "1",
            json!({"type":"export","scope":"branch","cursor":1,"delay_ms":0}),
            "",
        );
        let text = exported["text"].as_str().unwrap();
        let data: Value = serde_json::from_str(text).unwrap();
        assert_eq!(
            data["branches"][0]["controller_changes"]
                .as_array()
                .unwrap()
                .len(),
            1
        );
        assert_eq!(data["branches"][0]["controller_changes"][0]["position"], 1);
        let expected = step(&mut original, "1", &view);
        let mut loaded = BrowserEngine::new();
        let imported = file(
            &mut loaded,
            "0",
            json!({"type":"import","controllers":null}),
            text,
        );
        assert!(imported["error"].is_null(), "{imported}");
        for cursor in 0..=2 {
            let source = send(
                &mut original,
                "1",
                None,
                json!({"type":"history","branch":2,"cursor":cursor}),
            );
            let actual = send(
                &mut loaded,
                "1",
                None,
                json!({"type":"history","branch":0,"cursor":cursor}),
            );
            assert_eq!(actual["view"]["board"], source["view"]["board"]);
            assert_eq!(actual["view"]["controllers"], source["view"]["controllers"]);
        }
        let after = step(&mut loaded, "1", &imported["live_view"]);
        assert_eq!(after["board"], expected["board"]);
        // A future fork in the loaded linear history must use the checkpoint at that move.
        let fork = send(
            &mut loaded,
            "1",
            after["position_version"].as_str(),
            json!({"type":"fork","branch":0,"cursor":1,"replacements":[null,null]}),
        );
        assert_eq!(fork["view"]["controllers"][1]["kind"], "human");
    }
}
#[test]
fn bad_files_and_limits_fail_atomically_and_file_channel_exceeds_command_capacity() {
    let mut engine = BrowserEngine::new();
    let initial = send(
        &mut engine,
        "0",
        None,
        json!({"type":"create","game":"tictactoe"}),
    );
    let saved = file(
        &mut engine,
        "1",
        json!({"type":"export","scope":"session","cursor":0,"delay_ms":0}),
        "",
    );
    let text = saved["text"].as_str().unwrap();
    let mut bad: Value = serde_json::from_str(text).unwrap();
    bad["versions"]["agents"] = 99.into();
    let mut changes: Value = serde_json::from_str(text).unwrap();
    changes["branches"][0]["controller_changes"] =
        json!([{"position":1,"controllers":[{"kind":"human"},{"kind":"human"}]}]);
    changes["versions"]["format"] = 2.into();
    for (index, input) in [
        "{broken".to_string(),
        bad.to_string(),
        changes.to_string(),
        " ".repeat(10 * 1024 * 1024 + 1),
    ]
    .into_iter()
    .enumerate()
    {
        let reply = file(
            &mut engine,
            "1",
            json!({"type":"import","controllers":null}),
            &input,
        );
        assert!(reply["error"].is_object());
        if index == 1 {
            assert!(
                reply["error"]["message"]
                    .as_str()
                    .unwrap()
                    .contains("agents version/identity: file 99; supported 1")
            );
        }
        assert_eq!(reply["generation"], "1");
        assert_eq!(reply["request_id"], "9");
        let current = send(&mut engine, "1", None, json!({"type":"view"}));
        assert_eq!(current["view"], initial["view"]);
    }
    let padded = format!("{text}{}", " ".repeat(40_000));
    let reply = file(
        &mut engine,
        "1",
        json!({"type":"import","controllers":null}),
        &padded,
    );
    assert!(reply["error"].is_null(), "{reply}");
    assert_eq!(reply["generation"], "2");
    let stale = file(
        &mut engine,
        "1",
        json!({"type":"export","scope":"state","cursor":0,"delay_ms":0}),
        "",
    );
    assert_eq!(stale["error"]["code"], "stale_generation");
}
